// Synthetic fixtures for the test-suite.
//
// The container built here mirrors the layout used by the platform but the
// payload is a PDF generated by pdf-lib, so no copyrighted material is stored
// in this repository.

import crypto from 'node:crypto';
import { PDFDocument, StandardFonts } from 'pdf-lib';
import { encodeMeta } from '../../src/msgpack.mjs';

export const HEADER_LEN = 256;
export const TEST_KEY_B64 = Buffer.from('0123456789abcdef').toString('base64'); // 16 bytes

export async function makePdf({ pages = 1, text = 'Hello Hoepli' } = {}) {
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica);
  for (let i = 0; i < pages; i++) {
    const page = doc.addPage([300, 400]);
    page.drawText(`${text} ${i + 1}`, { x: 20, y: 350, size: 14, font });
  }
  return Buffer.from(await doc.save());
}

/**
 * Wrap a PDF into a container: 256 byte MessagePack header, an AES-CBC
 * encrypted prefix and a clear-text tail.
 */
export function makeContainer(pdf, { keyB64 = TEST_KEY_B64, prefixBytes = 300, filename = 'fixture.pdf' } = {}) {
  const key = Buffer.from(keyB64, 'base64');
  const prefix = pdf.subarray(0, prefixBytes);
  const tail = pdf.subarray(prefixBytes);

  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
  const ciphertext = Buffer.concat([cipher.update(prefix), cipher.final()]);

  const start = HEADER_LEN + iv.length + ciphertext.length;
  const meta = encodeMeta({
    filename,
    md5: crypto.createHash('md5').update(pdf).digest('hex'),
    orig_size: pdf.length,
    start,
    path: 'fixture',
  });
  const header = Buffer.alloc(HEADER_LEN);
  meta.copy(header, 0);
  return Buffer.concat([header, iv, ciphertext, tail]);
}
